let resolve_from_paths paths name =
  let fl =
    if Filename.is_relative name then
      List.map (fun p -> Filename.concat p name) paths
    else [name]
  in
    match List.filter is_file fl with
    | [] -> raise (FailedResolve fl)
    | [f] -> f
    | fl -> raise (AmbiguousResolve fl)

